Future<void> _expectStore(
  WidgetTester tester,
  _Device device,
  Locale locale,
  String screen, {
  String? fileBasename,
  bool disposeAfter = false,
}) async {
  // App Store devices land in test/goldens/goldens/store/<lang>/<device>/; the
  // Play devices land straight in the supply metadata tree with their
  // listing order prefix (Play sorts screenshots by file name).
  final String golden;
  switch (device.name) {
